using System;
using UnityEngine;
using UnityEngine.Rendering;
namespace DiwaliGameplay {
public sealed class DiyaRestTarget : MonoBehaviour {
 public Transform rest;public GrabbableItem item;public float radius=.6f;
 public Func<bool> isActive;
 Transform ghost;LineRenderer ring;TextMesh message;Material ghostMaterial,lineMaterial;
 public static bool Contains(GrabbableItem item,Transform rest,float radius){if(!item||!rest)return false;var d=item.transform.position-rest.position;return new Vector2(d.x,d.z).sqrMagnitude<=radius*radius&&d.y>=-1.1f&&d.y<=1.8f;}
 public static DiyaRestTarget Create(Transform parent,Transform rest,GrabbableItem item,float radius,Func<bool> isActive){var go=new GameObject(item.itemId+" ghost target");go.transform.SetParent(parent,false);var target=go.AddComponent<DiyaRestTarget>();target.rest=rest;target.item=item;target.radius=radius;target.isActive=isActive;target.Build();return target;}
 void Build(){var shader=Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Sprites/Default");ghostMaterial=new Material(shader);ghostMaterial.SetColor("_BaseColor",new Color(.2f,.9f,1,.2f));ghostMaterial.color=new Color(.2f,.9f,1,.2f);ghostMaterial.SetFloat("_Surface",1);ghostMaterial.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);ghostMaterial.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);ghostMaterial.SetFloat("_ZWrite",0);ghostMaterial.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");ghostMaterial.renderQueue=3000;lineMaterial=new Material(shader);lineMaterial.color=new Color(1,.72f,.2f);
 ghost=new GameObject("Matching mesh preview").transform;ghost.SetParent(transform,true);ghost.SetPositionAndRotation(item.transform.position,item.transform.rotation);
 foreach(var source in item.GetComponentsInChildren<MeshFilter>(true)){if(!source.sharedMesh)continue;var go=new GameObject(source.name+" ghost");go.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);go.transform.localScale=source.transform.lossyScale;go.transform.SetParent(ghost,true);go.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var renderer=go.AddComponent<MeshRenderer>();var mats=new Material[source.sharedMesh.subMeshCount];for(int i=0;i<mats.Length;i++)mats[i]=ghostMaterial;var original=source.GetComponent<MeshRenderer>();if(original&&mats.Length==3&&source.name.StartsWith("Sphere"))mats[0]=original.sharedMaterials[0];renderer.sharedMaterials=mats;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}
 var line=new GameObject("Forgiving horizontal drop area");line.transform.SetParent(transform,false);ring=line.AddComponent<LineRenderer>();ring.material=lineMaterial;ring.loop=true;ring.positionCount=48;ring.widthMultiplier=.012f;ring.useWorldSpace=true;
 var label=new GameObject("Placement readiness");label.transform.SetParent(transform,false);message=label.AddComponent<TextMesh>();message.fontSize=44;message.characterSize=.012f;message.anchor=TextAnchor.MiddleCenter;message.alignment=TextAlignment.Center;}
 void LateUpdate(){if(!rest||!item)return;bool active=isActive!=null&&isActive();ghost.gameObject.SetActive(active);ring.enabled=active;message.gameObject.SetActive(active);if(!active)return;ghost.SetPositionAndRotation(rest.position,rest.rotation);bool ready=item.WasGrabbed&&Contains(item,rest,radius);var color=ready?new Color(.25f,1,.55f):new Color(1,.72f,.2f);ring.startColor=ring.endColor=color;lineMaterial.color=color;ghostMaterial.SetColor("_BaseColor",new Color(color.r,color.g,color.b,.22f));for(int i=0;i<48;i++){float a=i*Mathf.PI*2/48;ring.SetPosition(i,rest.position+new Vector3(Mathf.Cos(a)*radius,-.05f,Mathf.Sin(a)*radius));}message.text=ready?"READY\nRelease to place":"PLACE HERE";message.color=color;message.transform.position=rest.position+Vector3.up*.2f;var camera=Camera.main;if(camera)message.transform.rotation=Quaternion.LookRotation(message.transform.position-camera.transform.position,camera.transform.up);}
 void OnDestroy(){if(ghostMaterial)Destroy(ghostMaterial);if(lineMaterial)Destroy(lineMaterial);}
}
}
